// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));

        MockToken mock = new MockToken();
        caddress = address(mock);

        bool success = c.transfer(from, caddress, _tos, v);
        assertTrue(success);

        uint expectedCalls = _tos.length;
        uint actualCalls = mock.transferFromCallCount();
        assertTrue(actualCalls == expectedCalls);
    }
}

contract MockToken {
    uint public transferFromCallCount;

    function transferFrom(address, address, uint256) external returns (bool) {
        transferFromCallCount++;
        return true;
    }
}
